package com.bank.deptreport;

import java.util.*;
import java.util.DoubleSummaryStatistics;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class DeptSummaryDemo {
    private static final Logger log = Logger.getLogger("DeptReport");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT", 1000000),
            new Employee("Amit", "IT", 600000),
            new Employee("Priya", "Sales", 900000));
        DeptReportService service = new DeptReportService();

        Map<String, DoubleSummaryStatistics> report = service.summarize(staff);
        report.forEach((dept, s) -> log.info(() -> dept
            + " count=" + s.getCount() + " total=" + s.getSum()
            + " min=" + s.getMin() + " max=" + s.getMax() + " avg=" + s.getAverage()));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final double salary;
    Employee(String name, String department, double salary) {
        this.name = name; this.department = department; this.salary = salary;
    }
    String getDepartment() { return department; }
    double getSalaryAsDouble() { return salary; }
}

// ─── Would be in service/DeptReportService.java ───
class DeptReportService {
    Map<String, DoubleSummaryStatistics> summarize(List<Employee> staff) {
        return staff.stream()
            .collect(groupingBy(Employee::getDepartment,
                summarizingDouble(Employee::getSalaryAsDouble)));  // 5 stats per dept, one pass
    }
}
